# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorLog {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface Props {
  children: ReactNode;
  fallback?: ReactNode | ((props: FallbackProps) => ReactNode);
  onError?: (log: ErrorLog) => void;
  onReset?: () => void;
  resetKeys?: unknown[];
  isolate?: boolean;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  errorCount: number;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  resetError: () => void;
  errorCount: number;
}

// ─── Error Logger ─────────────────────────────────────────────────────────────

class ErrorLogger {
  private static logs: ErrorLog[] = [];

  static log(error: Error, errorInfo: ErrorInfo): ErrorLog {
    const entry: ErrorLog = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? '',
    };

    this.logs.push(entry);

    // Console output with structured formatting
    console.group(
      `%c⚠ React Error Boundary — ${entry.timestamp.toISOString()}`,
      'color: #ef4444; font-weight: bold; font-size: 14px;'
    );
    console.error('Error:', error.message);
    console.error('Stack:', error.stack);
    console.error('Component Stack:', entry.componentStack);
    console.groupEnd();

    return entry;
  }

  static getLogs(): ErrorLog[] {
    return [...this.logs];
  }

  static clear(): void {
    this.logs = [];
  }
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({ error, errorInfo, resetError, errorCount }: FallbackProps) {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div style={styles.container} role="alert" aria-live="assertive">
      <div style={styles.card}>
        {/* Icon */}
        <div style={styles.iconWrapper}>
          <svg
            style={styles.icon}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            aria-hidden="true"
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="8" x2="12" y2="12" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </svg>
        </div>

        {/* Heading */}
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.subtext}>
          An unexpected error occurred while rendering this component.
          {errorCount > 1 && (
            <span style={styles.badge}> Error #{errorCount}</span>
          )}
        </p>

        {/* Error summary */}
        <div style={styles.errorBox} aria-label="Error message">
          <code style={styles.errorMessage}>{error.message}</code>
        </div>

        {/* Actions */}
        <div style={styles.actions}>
          <button
            style={styles.retryButton}
            onClick={resetError}
            onMouseEnter={(e) =>
              ((e.target as HTMLButtonElement).style.backgroundColor = '#2563eb')
            }
            onMouseLeave={(e) =>
              ((e.target as HTMLButtonElement).style.backgroundColor = '#3b82f6')
            }
            aria-label="Retry rendering the component"
          >
            ↺ Try Again
          </button>

          <button
            style={styles.detailsButton}
            onClick={() => setShowDetails((v) => !v)}
            aria-expanded={showDetails}
            aria-controls="error-details"
          >
            {showDetails ? '▲ Hide Details' : '▼ Show Details'}
          </button>
        </div>

        {/* Collapsible details */}
        {showDetails && (
          <details
            id="error-details"
            open
            style={styles.details}
          >
            <summary style={styles.detailsSummary}>Stack Trace</summary>
            <pre style={styles.pre}>{error.stack}</pre>

            <summary style={{ ...styles.detailsSummary, marginTop: 12 }}>
              Component Stack
            </summary>
            <pre style={styles.pre}>{errorInfo.componentStack}</pre>
          </details>
        )}
      </div>
    </div>
  );
}

// ─── Error Boundary Class ─────────────────────────────────────────────────────

export class ErrorBoundary extends Component<Props, State> {
  private prevResetKeys: unknown[];

  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      errorCount: 0,
    };
    this.prevResetKeys = props.resetKeys ?? [];
  }

  // Triggered during render phase — update state to show fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // Triggered after render — log the error
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const log = ErrorLogger.log(error, errorInfo);

    this.setState((prev) => ({
      errorInfo,
      errorCount: prev.errorCount + 1,
    }));

    this.props.onError?.(log);
  }

  // Watch for resetKeys changes to auto-reset
  componentDidUpdate(prevProps: Props): void {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    if (hasError && resetKeys && prevProps.resetKeys) {
      const changed = resetKeys.some(
        (key, idx) => key !== prevProps.resetKeys![idx]
      );
      if (changed) {
        this.resetError();
      }
    }
  }

  resetError = (): void => {
    this.props.onReset?.();
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  render(): ReactNode {
    const { hasError, error, errorInfo, errorCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && error && errorInfo) {
      const fallbackProps: FallbackProps = {
        error,
        errorInfo,
        resetError: this.resetError,
        errorCount,
      };

      // Custom fallback: render-prop or ReactNode
      if (typeof fallback === 'function') {
        return fallback(fallbackProps);
      }
      if (fallback) {
        return fallback;
      }

      return <DefaultFallback {...fallbackProps} />;
    }

    // isolate=true wraps children to prevent cascade
    return isolate ? <React.Fragment>{children}</React.Fragment> : children;
  }
}

