  },
  badge: {
    display: 'inline-block',
    backgroundColor: '#fee2e2',
    color: '#b91c1c',
    borderRadius: '9999px',
    padding: '2px 8px',
    fontSize: '12px',
    fontWeight: 600,
  },
  errorBox: {
    backgroundColor: '#fef2f2',
    border: '1px solid #fecaca',
    borderRadius: '8px',
