};

export default ErrorBoundary;
```

## Usage Examples

```tsx
// App.tsx — Usage demonstrations

import React, { useState } from 'react';
import ErrorBoundary, { FallbackProps } from './ErrorBoundary';

// ─── Buggy component for testing ─────────────────────────────────────────────

function BuggyCounter() {
  const [count, setCount] = useState(0);

  if (count >= 3) {
    throw new Error(`Counter exceeded limit: value was ${count}`);
  }

  return (
    <div style={{ textAlign: 'center', padding: 24 }}>
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c + 1)}>
        Increment (throws at 3)
      </button>
    </div>
  );
}

// ─── 1. Basic usage ───────────────────────────────────────────────────────────

export function BasicExample() {
  return (
    <ErrorBoundary>
      <BuggyCounter />
    </ErrorBoundary>
  );
}

// ─── 2. Custom render-prop fallback ───────────────────────────────────────────

function CustomFallback({ error, resetError, errorCount }: FallbackProps) {
  return (
    <div style={{ padding: 24, border: '2px dashed tomato', borderRadius: 8 }}>
      <h3>💥 Custom Error UI</h3>
      <p>{error.message}</p>
      <p>This has crashed {errorCount} time(s).</p>
      <button onClick={resetError}>Retry</button>
    </div>
  );
}

export function CustomFallbackExample() {
  return (
    <ErrorBoundary fallback={(props) => <CustomFallback {...props} />}>
      <BuggyCounter />
    </ErrorBoundary>
  );
}

// ─── 3. resetKeys — auto-reset when a prop changes ───────────────────────────

export function ResetKeysExample() {
  const [userId, setUserId] = useState(1);

  return (
    <div>
      <button onClick={() => setUserId((id) => id + 1)}>
        Load next user (resets boundary)
      </button>

      <ErrorBoundary
        resetKeys={[userId]}
        onReset={() => console.log('Boundary reset for user', userId)}
      >
        <BuggyCounter key={userId} />
      </ErrorBoundary>
    </div>
  );
}

// ─── 4. External error logging (e.g. Sentry) ─────────────────────────────────

export function WithLoggingExample() {
  return (
    <ErrorBoundary
      onError={({ error, timestamp, componentStack }) => {
        // Replace with your real error reporting service
        console.log('[Sentry/Datadog] Reporting error:', {
          message: error.message,
          timestamp,
          componentStack,
        });
      }}
    >
      <BuggyCounter />
    </ErrorBoundary>
  );
}

// ─── 5. Nested boundaries for isolated sections ───────────────────────────────

export function NestedBoundariesExample() {
  return (
    <ErrorBoundary fallback={<p>⚠ Page-level error</p>}>
      <main>
        <h1>Dashboard</h1>

        <ErrorBoundary
          isolate
          fallback={<p>⚠ Widget A failed — rest of page still works</p>}
        >
          <BuggyCounter />
        </ErrorBoundary>

        <ErrorBoundary
          isolate
          fallback={<p>⚠ Widget B failed</p>}
        >
          <BuggyCounter />
        </ErrorBoundary>
      </main>
    </ErrorBoundary>
  );
}
```

## Architecture Overview

```
┌─────────────────────────────────────────────────────────┐
│                     ErrorBoundary                        │
│                                                          │
│  Props:                                                  │
│  ├── children        — wrapped subtree                   │
│  ├── fallback        — ReactNode | render-prop           │
│  ├── onError()       — external logging hook             │
│  ├── onReset()       — called before state reset         │
│  ├── resetKeys[]     — auto-reset on value change        │
│  └── isolate         — prevent cascade to parent         │
│                                                          │
│  Lifecycle:                                              │
